-- Cyclone Magnum targeted additive data completion. Frankfurt only.
begin;
create temporary table cyclone_input on commit drop as select * from jsonb_to_recordset($data$[{"id": "efd6902b-f080-5165-8a13-0375c1d32298", "item": "19412", "name": "Cyclone Magnum", "year": 1996, "chassis": "Super TZ", "jan": "4950344061426", "src": "https://www.tamiya.com/japan/products/19412/index.html", "jsrc": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603060160", "en": "The standard Cyclone Magnum kit on the Super TZ chassis, with compact wheel cowls, a large rear wing and white body with blue and red graphics. First introduced in 1996; later production under the same item is represented here without certifying a particular box as a first-run original.", "it": "Cyclone Magnum su telaio Super TZ, con passaruota compatti, grande ala posteriore e carrozzeria bianca con grafica blu e rossa. Introdotta nel 1996; la scheda comprende le successive produzioni dello stesso articolo, senza attribuire automaticamente una confezione alla prima tiratura.", "typ": "original", "date": null, "rarity": null, "status": "unknown", "color": "White", "img": "https://www.tamiya.com/japan_contents/img/usr/item/1/19412/19412_1.jpg"}, {"id": "ab1e0fb4-026b-5971-8745-96813278c958", "item": "19417", "name": "Cyclone Magnum TRF", "year": 1997, "chassis": "Super TZ", "jan": "4950344061471", "src": "https://www.tamiya.com/japan/products/19417/index.html", "jsrc": "https://hs-tamtam.co.jp/product/detail/232976/", "en": "TRF version of the Cyclone Magnum with a lightened body, open cockpit and cowls, slotted rear wing and white wheels. Complete Super TZ chassis assembly kit.", "it": "Versione TRF della Cyclone Magnum, con carrozzeria alleggerita, aperture su abitacolo e passaruota, ala posteriore con feritoie e cerchi bianchi. Kit completo su telaio Super TZ.", "typ": "special", "date": null, "rarity": "Common", "status": "unknown", "color": "White", "img": "https://www.tamiya.com/japan_contents/img/usr/item/1/19417/19417_1.jpg"}, {"id": "85a3549a-d563-5dda-bc6d-bd1ac684601e", "item": "19440", "name": "Cyclone Magnum Premium", "year": 2014, "chassis": "AR", "jan": "4950344064090", "src": "https://www.tamiya.com/japan/products/19440/index.html", "jsrc": "https://www.centralline.jp/products/4950344064090", "en": "Premium version on the AR chassis, with metallic-grey chassis, blue low-friction parts, white body and fluorescent green wheels. Distinct from the Super TZ standard kit.", "it": "Versione Premium su telaio AR grigio metallizzato, con parti a basso attrito blu, carrozzeria bianca e cerchi verde fluorescente. Edizione distinta dal kit standard su Super TZ.", "typ": "premium", "date": "2014-11-21", "rarity": "Common", "status": "unknown", "color": "White", "img": "https://www.tamiya.com/japan_contents/img/usr/item/1/19440/19440_1.jpg"}, {"id": "ccf7a1c0-fee0-5f6d-894e-d3bb10d1e808", "item": "94486", "name": "Cyclone Magnum Limited Special — Blue Plated", "year": 2003, "chassis": "Super TZ", "jan": "4950344944866", "src": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603021767", "jsrc": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603021767", "en": "Limited Special complete kit featuring a blue-plated Cyclone Magnum body, translucent smoke Super TZ chassis and green wheels.", "it": "Kit completo Limited Special con carrozzeria Cyclone Magnum cromata blu, telaio Super TZ fumé traslucido e cerchi verdi.", "typ": "color_special", "date": null, "rarity": null, "status": "unknown", "color": "Blue Plated", "img": "https://cdn.suruga-ya.jp/database/pics_webp/game/603021767.jpg.webp"}, {"id": "27868827-a5c4-5301-990c-a9920d57defb", "item": "94488", "name": "Cyclone Magnum TRF Limited Special — Purple Plated", "year": 2003, "chassis": "Super TZ", "jan": "4950344944880", "src": "https://www.hlj.com/cyclone-magnum-trf-limited-special-tam94488", "jsrc": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603072652", "en": "Limited Special complete kit featuring the TRF body in purple plating, translucent smoke Super TZ chassis and white wheels.", "it": "Kit completo Limited Special con carrozzeria TRF cromata viola, telaio Super TZ fumé traslucido e cerchi bianchi.", "typ": "color_special", "date": null, "rarity": null, "status": "unknown", "color": "Purple Plated", "img": "https://cdn.suruga-ya.jp/database/pics_webp/game/603072652.jpg.webp"}, {"id": "de72510e-f1d4-5481-b0ae-3ea8ba806010", "item": "94620", "name": "Cyclone Magnum Special Kit + Hurricane Sonic Body", "year": 2007, "chassis": "Super TZ", "jan": "4950344946204", "src": "https://www.hlj.com/cyclone-magnum-sp-kit-hurricane-sonic-body-tam94620", "jsrc": "https://www.1999.co.jp/10266162", "en": "Cyclone Magnum complete Super TZ kit supplied with an additional Hurricane Sonic body and stickers. The box contains one chassis, not two complete cars.", "it": "Kit completo Cyclone Magnum su Super TZ con carrozzeria e adesivi Hurricane Sonic aggiuntivi. La confezione contiene un solo telaio, non due vetture complete.", "typ": "special", "date": null, "rarity": null, "status": "discontinued", "color": "White", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/94620/94620_1.jpg"}, {"id": "4c27c658-c6de-5a8e-84a4-840ac6323543", "item": "95126", "name": "Cyclone Magnum Memorial — 25th Anniversary", "year": 2019, "chassis": "Super TZ-X", "jan": "4950344951260", "src": "https://www.tamiya.com/japan/products/95126/index.html", "jsrc": "https://www.plazajapan.com/4950344951260/", "en": "Fully Cowled Mini 4WD 25th Anniversary kit with clear polycarbonate body, white Super TZ-X chassis with commemorative marking and green spiral-spoke wheels.", "it": "Kit del 25° anniversario delle Fully Cowled Mini 4WD con carrozzeria in policarbonato trasparente, telaio Super TZ-X bianco con marcatura commemorativa e cerchi verdi a spirale.", "typ": "anniversary", "date": "2019-11-02", "rarity": null, "status": "unknown", "color": "Clear", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/95126/95126_1.jpg"}, {"id": "6147d13f-b349-52e8-b21b-e19d8b5539f8", "item": "95676", "name": "Cyclone Magnum Polycarbonate Body Special — 30th Anniversary", "year": 2024, "chassis": "AR", "jan": "4950344956760", "src": "https://www.tamiya.com/japan/products/95676/index.html", "jsrc": "https://www.suruga-ya.jp/kaitori/kaitori_detail/603202430", "en": "Fully Cowled Mini 4WD 30th Anniversary complete kit with clear polycarbonate body, white AR chassis, green spiral-spoke wheels, super-hard low-profile tires and blue anniversary sticker.", "it": "Kit completo del 30° anniversario delle Fully Cowled Mini 4WD con carrozzeria in policarbonato trasparente, telaio AR bianco, cerchi verdi a spirale, pneumatici ribassati super hard e adesivo anniversario blu.", "typ": "anniversary", "date": "2024-10-12", "rarity": null, "status": "unknown", "color": "Clear", "img": "https://www.tamiya.com/japan_contents/img/usr/item/9/95676/95676_1.jpg"}]$data$::jsonb) as t(id uuid,item text,name text,year integer,chassis text,jan text,src text,jsrc text,en text,it text,typ text,date date,rarity text,status text,color text,img text);
do $$begin
 if not exists(select 1 from products where id='53791485-2948-5176-8acb-2ec947eafc51' and metadata->>'launch_status'='coming_soon') then raise exception 'Family baseline changed'; end if;
 if exists(select 1 from cyclone_input i join product_releases r on r.item_number=i.item or r.barcode_jan=i.jan where r.id<>i.id) then raise exception 'Identity conflict'; end if;
end$$;
insert into product_releases(id,product_id,item_number,release_type,edition_type,edition_name,release_year,release_date,chassis,barcode_jan,color,description,description_it,discontinued,is_original,rarity,data_source,verification_status,production_status,catalog_visibility,catalog_visibility_reason)
select id,'53791485-2948-5176-8acb-2ec947eafc51',item,case when typ='color_special' then 'Color Special' when typ='premium' then 'Premium' else 'Special Edition' end,typ,name,year,date,chassis,jan,color,en,it,status='discontinued',false,rarity,'family_audit_20261102','verified',status,'public','Verified exact complete-kit identity and exact/high-confidence release photograph' from cyclone_input on conflict(id) do nothing;
update product_releases r set barcode_jan=i.jan,description=i.en,description_it=i.it,rarity=coalesce(i.rarity,r.rarity),updated_at=now() from cyclone_input i where r.id=i.id and r.product_id='53791485-2948-5176-8acb-2ec947eafc51';
insert into release_images(release_id,url,position) select id,img,0 from cyclone_input i where not exists(select 1 from release_images x where x.release_id=i.id and x.url=i.img);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,case when src like 'https://www.tamiya.com/%' then 'official_manufacturer' else 'trusted_secondary' end,src,array['item_number','edition_name','chassis','description','description_it'],'2026-11-02','Exact complete kit audited; years/date limits and production waves documented in docs/CYCLONE_MAGNUM_FAMILY_AUDIT_2026-11-02.md. Buyback amounts and old retail prices not imported as current offers.' from cyclone_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.src);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,'trusted_secondary',jsrc,array['barcode_jan'],'2026-11-02','Exact kit JAN, checksum validated. Current-generation barcode does not by itself prove a first-run box.' from cyclone_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.jsrc and 'barcode_jan'=any(x.verified_fields));
insert into release_identifiers(release_id,scheme,value,market,is_primary,verification_status,source_url,checked_at)
select id,'JAN',jan,null,true,'verified',jsrc,'2026-11-02' from cyclone_input i where not exists(select 1 from release_identifiers x where x.release_id=i.id and x.scheme='JAN' and x.value=i.jan);
insert into release_sources(release_id,source_type,source_url,verified_fields,checked_at,notes)
select id,'other',img,array['release_images.url'],'2026-11-02','Exact official assembled image or labelled exact-edition box inspected visually. Next Image HTTP200 checked; no sibling fallback or license claim.' from cyclone_input i where not exists(select 1 from release_sources x where x.release_id=i.id and x.source_url=i.img);
select trackdash_enroll_release_market_scans(id) from cyclone_input;
update market_scan_queue q set next_scan_at=now(),updated_at=now() where q.release_id in(select id from cyclone_input) and q.source_id=(select id from price_sources where slug='ebay_active_public') and q.enabled and q.last_attempt_at is null;
update market_scan_queue set enabled=false,next_scan_at='2099-01-01' where release_id in(select id from cyclone_input) and source_id=(select id from price_sources where slug='rcjaz_public');
update market_scan_targets set enabled=false,next_scan_at='2099-01-01' where release_id in(select id from cyclone_input) and source_id=(select id from price_sources where slug='rcjaz_public');
select trackdash_enqueue_market_recompute(id,'new_complete_unbuilt') from cyclone_input;
commit;
select item_number,id,barcode_jan from product_releases where product_id='53791485-2948-5176-8acb-2ec947eafc51' order by item_number;
